-- Deities and Demigods: Asgardian pantheon divine stat blocks, batch C.
-- Source: Deities and Demigods (2002), Chapter 6, pp. 180-186.
-- Printed 3.0 statistics remain source-of-truth; official 3.5 conversion deltas are recorded separately.

INSERT OR IGNORE INTO dnd35_sources
  (id,slug,name,abbreviation,publisher,system,edition,description,url,is_official,is_homebrew,owner_user_id)
VALUES ('dd-3.0','deities-and-demigods-3-0','Deities and Demigods','DD','Wizards of the Coast','dnd','3.0',
        'Deities and Demigods (2002): divine ranks, pantheons, salient divine abilities, divine minions, domains, spells, monsters, prestige classes, and ascension.',NULL,1,0,NULL);

UPDATE dnd35_deities SET symbol='Her face' WHERE source_id='dd-3.0' AND slug='hel' AND owner_user_id IS NULL;
UPDATE dnd35_deities SET symbol='Winged scroll' WHERE source_id='dd-3.0' AND slug='hermod' AND owner_user_id IS NULL;
UPDATE dnd35_deities SET symbol='Flame' WHERE source_id='dd-3.0' AND slug='loki' AND owner_user_id IS NULL;
UPDATE dnd35_deities SET symbol='Gold coin' WHERE source_id='dd-3.0' AND slug='njord' AND owner_user_id IS NULL;

WITH desired(slug,name,page,description,mechanics) AS (VALUES
('dd-statblock-hel','Hel Divine Stat Block','180-181',
 'Hel is the divine-rank-15 intermediate Asgardian deity of death and the underworld of Niflheim.',
 '{"deitySlug":"hel","pantheon":"asgardian","sourceEdition":"3.0","rankBand":"intermediate","divineRank":15,"titles":["Goddess of Death and the Underworld"],"symbol":"Her face","homePlane":"Niflheim","alignment":"NE","classes":[{"class":"Cleric","level":20},{"class":"Wizard","level":20}],"creature":{"type":"Outsider","size":"Medium","hitDice":"20d8+180 outsider + 20d8+180 cleric + 20d4+180 wizard","hitPoints":940,"initiative":12,"speed":{"land":60},"armorClass":{"total":69,"dexterity":8,"divine":15,"natural":28,"deflection":8},"face":"5 ft. by 5 ft.","reachFeet":5},"attacks":{"longsword":"+69/+64/+59/+54 melee, +5 unholy wounding longsword of disease","longswordDamage":"1d8+17/17-20 plus disease as contagion","spellTouch":{"melee":63,"ranged":63}},"saves":{"fort":58,"ref":55,"will":60},"abilities":{"str":27,"dex":27,"con":29,"int":44,"wis":32,"cha":27},"specialAttacks":{"rebukeUndeadPerDay":19,"frightfulPresence":"Takes effect when Hel reveals the rotting side of her face."},"specialQualities":{"printedDamageReduction":"50/+4","fastHealing":35,"spellResistance":47,"divineAura":{"radiusFeet":1500,"dc":33},"familiar":"rats","teleportWithoutErrorAtWill":true,"planeShiftAtWill":true},"salientDivineAbilities":["Alter Size","Annihilating Strike","Arcane Mastery","Automatic Metamagic (quicken wizard spells)","Banestrike (good outsiders)","Call Creatures (undead)","Divine Fast Healing","Divine Inspiration (dread)","Divine Spell Focus (Necromancy)","Extra Energy Immunity (fire)","Frightful Presence","Hand of Death","Life and Death","Life Drain","Rejuvenation","Spontaneous Wizard Spells","Undead Mastery","Undead Qualities"],"domainPowers":{"deathTouchUsesPerDay":15,"deathTouchDice":"20d6","destructionSmiteUsesPerDay":15,"destructionSmiteAttackBonus":4,"destructionSmiteDamageBonus":20,"evilSpellsCasterLevelBonus":1},"spellLikeAbilities":{"casterLevel":25,"evilCasterLevel":26,"saveDc":"33 + spell level"},"spellcasting":{"clericSpellsPerDay":"6/9/9/9/8/8/7/7/6/6","clericBaseDc":"21 + spell level","clericNecromancyBaseDc":"36 + spell level","wizardSpellsPerDay":"4/9/8/8/8/8/7/7/7/7","wizardBaseDc":"27 + spell level","wizardNecromancyBaseDc":"42 + spell level"},"portfolioSense":"Deaths by disease, accident, or poison involving one or more people, plus events in graveyards; instantaneously and fifteen weeks into the past.","automaticActions":{"skills":["Alchemy","Intimidate","Sense Motive"],"freeActionDcMaximum":25,"maximumPerRound":10},"createMagicItems":{"scope":"items that cause damage, have an evil alignment, or impose a penalty on one or more targets","maximumMarketPriceGp":200000},"avatarStatus":"No Avatar salient divine ability is present in the printed stat block; no avatar stat block is created.","revision3_5":{"alignmentSubtypes":["evil"],"damageReduction":"25/epic","rankBasedFireResistance":20,"fireImmunityFromSalientAbility":true,"additionalOutsiderSkillPoints":true,"cleric":"No class-feature change in the official revision.","wizard":"Apply revised school-specialization rules if relevant.","divineSpellFocus":"Increase the affected school save DC by one-half divine rank rather than the full divine rank; preserve the rule rather than silently reusing the printed 3.0 Necromancy DCs.","divineInspirationDread":"Uses the revised crushing despair model: affected creatures take -4 on attacks, damage, saves, and checks.","undeadQualities":"Use the revised Monster Manual undead qualities.","destructionDomain":"circle of doom is renamed mass inflict light wounds under the official revision.","defunctSkills":["Alchemy -> Craft (alchemy)","Innuendo ranks reassigned","Intuit Direction migrated","Scry ranks reassigned"]}}'),

('dd-statblock-hermod','Hermod Divine Stat Block','182-183',
 'Hermod is the divine-rank-3 Asgardian demigod of luck, communication, freedom, and divine messages.',
 '{"deitySlug":"hermod","pantheon":"asgardian","sourceEdition":"3.0","rankBand":"demigod","divineRank":3,"titles":["Messenger of the Gods","The Nimble"],"symbol":"Winged scroll","homePlane":"Asgard","alignment":"CN","classes":[{"class":"Barbarian","level":20},{"class":"Bard","level":20}],"creature":{"type":"Outsider","size":"Medium","hitDice":"20d8+320 outsider + 20d12+320 barbarian + 20d6+320 bard","hitPoints":1480,"initiative":14,"speed":{"land":70},"armorClass":{"total":46,"dexterity":10,"divine":3,"natural":16,"deflection":7},"face":"5 ft. by 5 ft.","reachFeet":5},"attacks":{"rapier":"+59/+59/+54/+49/+44 melee, +5 speed rapier","dagger":"+55/+50 melee, +5 chaotic keen dagger","rapierDamage":"1d6+12/15-20","daggerDamage":"1d4+12/17-20","spellTouch":{"melee":50,"ranged":53}},"saves":{"fort":51,"ref":45,"will":43},"abilities":{"str":25,"dex":30,"con":42,"int":25,"wis":26,"cha":25},"specialQualities":{"printedDamageReduction":"38/+4 (4/-)","printedFireResistance":23,"spellResistance":35,"divineAura":{"radiusFeet":30,"dc":20},"bardicKnowledgeBonus":27,"bardicMusicUsesPerDay":20,"uncannyDodge":"cannot be flanked, +4 against traps","greaterRageUsesPerDay":6,"teleportWithoutErrorAtWill":true},"salientDivineAbilities":["Divine Celerity","Divine Dodge","Power of Luck","Stride"],"domainPowers":{"chaosSpellsCasterLevelBonus":1,"luckRerollsPerDay":3,"freedomOfMovementRoundsPerDay":3},"spellLikeAbilities":{"casterLevel":13,"chaosCasterLevel":14,"saveDc":"20 + spell level"},"greaterRage":{"printedArmorClass":44,"printedHitPoints":1660,"printedAttacks":"rapier +62/+62/+57/+52/+47 and dagger +58/+53","printedFort":54,"printedWill":46,"printedStr":31,"printedCon":48,"durationRounds":22,"notWindedAfterward":true},"spellcasting":{"bardSpellsKnownPerDay":"4/6/6/6/5/5/5","bardBaseDc":"17 + spell level"},"portfolioSense":"Movement or transmission of goods or information involving one thousand or more people, instantaneously.","automaticActions":{"skills":["Diplomacy","Escape Artist","Gather Information","Innuendo","Listen","Ride","Sense Motive"],"freeActionDcMaximum":15,"maximumPerRound":2},"createMagicItems":{"scope":"items related to communication, movement, travel, or overcoming obstacles","maximumMarketPriceGp":4500},"avatarStatus":"Hermod is rank 3 and does not possess the Avatar salient divine ability; no avatar stat block is created.","revision3_5":{"alignmentSubtypes":["chaotic"],"damageReduction":"15/epic","fireResistance":8,"additionalOutsiderSkillPoints":true,"barbarian":{"trapSenseIncrease":2,"classDamageReduction":"5/- instead of 4/-","mightyRage":"The revised 20th-level barbarian mighty rage adds an additional +2 Strength and Constitution and +1 Will save compared with the 3.0 value; Hermod lacks Divine Rage, so the class update applies.","indomitableWillBonusAgainstEnchantmentWhileRaging":4},"bard":{"inspireCourageBonus":4,"suggestionSaveDcIncrease":7,"newBardicMusic":["song of freedom","inspire heroics","mass suggestion"],"additionalSkillPoints":40},"divineCelerity":"Uses revised haste.","twoWeaponFighting":"Ambidexterity is obsolete in 3.5; recalculate the printed two-weapon feat chain using revised Two-Weapon Fighting rules rather than preserving Ambidexterity as a live feat.","travelDomain":"Use longstrider instead of expeditious retreat and greater teleport instead of teleport without error where the revised spell list applies.","defunctSkills":["Innuendo ranks reassigned","Intuit Direction migrated","Wilderness Lore -> Survival"]}}'),

('dd-statblock-loki','Loki Divine Stat Block','183-184',
 'Loki is the divine-rank-16 greater Asgardian deity of thieves, trickery, murder, chaos, and subversion.',
 '{"deitySlug":"loki","pantheon":"asgardian","sourceEdition":"3.0","rankBand":"greater","divineRank":16,"titles":["God of Mischief, Strife, and Fire","The Sly One","The Trickster","The Shape Changer","The Sky Traveler"],"symbol":"Flame","homePlane":"Asgard before Balder''s death; Midgard afterward","alignment":"CE","classes":[{"class":"Rogue","level":20},{"class":"Sorcerer","level":20}],"creature":{"type":"Outsider","size":"Medium","hitDice":"20d8+160 outsider + 20d6+160 rogue + 20d4+160 sorcerer","hitPoints":840,"initiative":"+15, always first","speed":{"land":60},"armorClass":{"total":83,"dexterity":11,"divine":16,"natural":29,"deflection":17},"face":"5 ft. by 5 ft.","reachFeet":5},"attacks":{"dagger":"+73/+68/+63/+58 melee, +5 chaotic unholy dagger of venom","daggerDamage":"1d4+13/17-20 plus deathblade poison DC 20, 1d6 Con initial/2d6 Con secondary; greater deity maximum base weapon damage 17","spellTouch":{"melee":64,"ranged":67},"greaterDeityAlways20OnAttacks":true,"greaterDeityMaximumDamage":true},"saves":{"fort":56,"ref":59,"will":56,"greaterDeityAlways20":true},"abilities":{"str":27,"dex":32,"con":27,"int":29,"wis":27,"cha":44},"specialAttacks":{"sneakAttack":"+13d6","cripplingStrike":true,"opportunist":true},"specialQualities":{"printedDamageReduction":"51/+4","spellResistance":48,"divineAura":{"radiusMiles":16,"dc":43},"familiar":"wolves","rogueFeatures":["evasion","defensive roll","improved evasion","uncanny dodge (cannot be flanked, +4 against traps)"],"teleportWithoutErrorAtWill":true,"planeShiftAtWill":true},"salientDivineAbilities":["Alter Form","Alter Reality","Alter Size","Automatic Metamagic (quicken sorcerer spells)","Battlesense","Divine Celerity","Divine Dodge","Divine Glibness","Divine Rogue","Divine Sneak Attack","Extra Domain (Destruction)","Extra Energy Immunity (fire)","Hand of Death","Instant Counterspell","Life and Death","Mass Life and Death","Shapechange","Supreme Initiative","True Shapechange","Wave of Chaos","Wound Enemy"],"domainPowers":{"chaosSpellsCasterLevelBonus":1,"destructionSmiteUsesPerDay":16,"destructionSmiteAttackBonus":4,"destructionSmiteDamageBonus":16,"evilSpellsCasterLevelBonus":1},"spellLikeAbilities":{"casterLevel":26,"chaosEvilCasterLevel":27,"saveDc":"43 + spell level"},"spellcasting":{"sorcererSpellsKnownPerDay":"6/11/10/10/10/10/9/9/9/9","sorcererBaseDc":"27 + spell level"},"portfolioSense":"All crimes, confidence games, practical jokes, and tricks, instantaneously and sixteen weeks into past and future.","automaticActions":{"skills":"any rogue class skill","freeActionDcMaximum":30,"maximumPerRound":20},"createMagicItems":"Any magic item related to rogues or assassins.","avatarStatus":"No Avatar salient divine ability is present in the printed stat block; no avatar stat block is created.","revision3_5":{"alignmentSubtypes":["chaotic","evil"],"damageReduction":"30/epic","rankBasedFireResistance":21,"fireImmunityFromSalientAbility":true,"additionalOutsiderSkillPoints":true,"rogue":"Additional +2 against traps under revised rogue rules.","sorcerer":"No class-feature change in the official revision.","battlesense":"Replaces uncanny dodge and improved uncanny dodge, superseding those printed rogue defenses where they overlap.","divineCelerity":"Uses revised haste.","destructionDomain":"circle of doom is renamed mass inflict light wounds.","trickeryDomain":"change self is renamed disguise self under the official revision.","defunctSkills":["Alchemy -> Craft (alchemy)","Innuendo ranks reassigned","Pick Pocket -> Sleight of Hand","Read Lips folded into Spot","Scry ranks reassigned"]}}'),

('dd-statblock-njord','Njord Divine Stat Block','184-186',
 'Njord is the divine-rank-11 intermediate Asgardian deity of commerce, the sea, and wind.',
 '{"deitySlug":"njord","pantheon":"asgardian","sourceEdition":"3.0","rankBand":"intermediate","divineRank":11,"titles":["God of the Sea and Winds"],"symbol":"Gold coin","homePlane":"Asgard","alignment":"NG","classes":[{"class":"Ranger","level":20},{"class":"Rogue","level":20}],"creature":{"type":"Outsider","size":"Medium","hitDice":"20d8+200 outsider + 20d10+200 ranger + 20d6+200 rogue","hitPoints":1080,"initiative":12,"speed":{"land":60,"swim":100},"armorClass":{"total":61,"dexterity":8,"divine":11,"natural":24,"deflection":8},"face":"5 ft. by 5 ft.","reachFeet":5},"attacks":{"longspear":"+72/+67/+62/+57 melee, +5 bane icy burst longspear","longspearVsGiants":"+74/+69/+64/+59 melee","longspearDamage":"1d8+27/19-20/x3","longspearDamageVsGiants":"2d6 plus 1d8+27/19-20/x3","spellTouch":{"melee":66,"ranged":59}},"saves":{"fort":53,"ref":51,"will":54},"abilities":{"str":41,"dex":26,"con":31,"int":26,"wis":28,"cha":26},"specialAttacks":{"sneakAttack":"+10d6","cripplingStrike":true,"opportunist":true},"specialQualities":{"printedDamageReduction":"46/+4","spellResistance":43,"divineAura":{"radiusFeet":1100,"dc":29},"elfTraits":true,"printedFavoredEnemies":{"giants":5,"goblinoids":4,"dragons":3,"aberrations":2,"undead":1},"rogueFeatures":["evasion","uncanny dodge (cannot be flanked, +4 against traps)","defensive roll","improved evasion"],"teleportWithoutErrorAtWill":true,"planeShiftAtWill":true},"salientDivineAbilities":["Alter Form","Alter Size","Banestrike (giants)","Call Creatures (sea animals)","Divine Storm","Divine Water Mastery","Energy Storm (positive energy)","Extra Energy Immunity (fire)","Gift of Life","Life and Death","Mind of the Beast","Power of Nature","Shapechange","Speak with Creatures (sea animals)"],"domainPowers":{"airTurningUsesPerDay":11,"goodSpellsCasterLevelBonus":1,"waterTurningUsesPerDay":11},"spellLikeAbilities":{"casterLevel":21,"goodCasterLevel":22,"saveDc":"29 + spell level"},"spellcasting":{"rangerSpellsPerDay":"6/5/5/5","rangerBaseDc":"19 + spell level"},"portfolioSense":"Any merchant or coastal fishing vessel setting sail and any business negotiation involving such vessels; instantaneously and eleven weeks into the past.","automaticActions":{"skills":["Appraise","Diplomacy","Profession (sailor)","Use Rope","Wilderness Lore"],"freeActionDcMaximum":25,"maximumPerRound":10},"createMagicItems":{"scope":"items related to building or sailing ships or fishing","maximumMarketPriceGp":200000},"avatarStatus":"No Avatar salient divine ability is present in the printed stat block; no avatar stat block is created.","revision3_5":{"alignmentSubtypes":["good"],"damageReduction":"25/epic","rankBasedFireResistance":16,"fireImmunityFromSalientAbility":true,"additionalOutsiderSkillPoints":true,"ranger":{"hitDice":"20d8 instead of 20d10","convertedHitPoints":1040,"additionalSkillPoints":40,"wildEmpathy":true,"favoredEnemyBonusTotal":18,"favoredEnemyDistributionNote":"The official update gives only the total +18 under revised ranger rules; do not invent a replacement per-enemy distribution.","combatStyle":"Recalculate using revised ranger combat-style feats.","bonusAndClassFeatures":["Endurance","woodland stride","swift tracker","evasion","camouflage","hide in plain sight"]},"rogue":"Additional +2 against traps under revised rogue rules.","defunctSkills":["Innuendo ranks reassigned","Intuit Direction migrated","Scry ranks reassigned","Wilderness Lore -> Survival"]}}')
)
INSERT INTO dnd35_rules
  (id,source_id,source_page,slug,name,description,rules_text,is_homebrew,owner_user_id,is_enabled,
   category,kind,is_variant,default_enabled,parent_slug,supersedes_slug,tags,mechanics)
SELECT
  'dd-rule-'||d.slug,'dd-3.0',d.page,d.slug,d.name,d.description,
  'Use the structured mechanics payload for the printed Deities and Demigods divine stat block. Printed 3.0 values remain source-of-truth; revision3_5 records official conversion deltas.',
  0,NULL,1,'deity','divine-stat-block',0,1,'dd-asgardian-pantheon',NULL,
  '["deities-and-demigods","asgardian","deity-stat-block","revision-3.5"]',
  d.mechanics
FROM desired d
WHERE NOT EXISTS (
  SELECT 1 FROM dnd35_rules r WHERE r.source_id='dd-3.0' AND r.slug=d.slug AND r.owner_user_id IS NULL
);